// Полная база: 45 архетипов + 45 теней + 30 связок тегов + картинки карт
var ARCHETYPES = [
  {"name": "Адепт", "tag": "Проводник", "podacha": "Точность движений выдаёт годы отработки — ты всё равно возвращаешься к простому упражнению, будто только начинаешь. Мастерство держится на верности основе, а сложное рядом с тобой перестаёт быть страшным.", "napravleniya": "преподавание мастер-классов, наставничество и менторство, духовные и ритуальные практики, хирургия и точные ремёсла, обучение боевым искусствам, экспертное консультирование, режиссура сложных постановок", "devoz": "Мастерство отточено настолько, что перестаёт быть заметным — заметен только результат.", "vizual": "простая одежда без украшений, руки, сложенные в жесте передачи", "image": "cards/archetype/Адепт.jpg"},
  {"name": "Союзник", "tag": "Даритель", "podacha": "Подставляешь плечо ровно там, где не хватает сил, и умеешь вовремя отойти, когда опора больше не нужна. Люди чувствуют разницу между тем, кто спасает, и тем, кто просто рядом, — и выбирают тебя.", "napravleniya": "партнёрство и совместные предприятия, менторство стартапов, корпоративное и семейное посредничество, тренерский штаб в спорте, юридическое сопровождение сделок и союзов, фонды взаимопомощи, кризисное консультирование", "devoz": "Сила соединяется там, где один даёт то, чего не хватает другому.", "vizual": "рука на плече в нужный момент, не раньше", "image": "cards/archetype/Союзник.jpg"},
  {"name": "Ангел", "tag": "Даритель", "podacha": "Добро делаешь и не выставляешь счёт — через день уже не помнишь имён, кому помогаешь чаще всего. Люди рядом с тобой на минуту перестают защищаться: никто здесь ничего не потребует взамен.", "napravleniya": "хосписная и паллиативная помощь, благотворительность и волонтёрство, социальная работа, уход за тяжелобольными, духовное сопровождение, работа с пострадавшими и беженцами, фонды донорской помощи", "devoz": "Доброта без расчёта — единственная, которая не требует возврата.", "vizual": "светлая ткань, тихий голос без нажима", "image": "cards/archetype/Ангел.jpg"},
  {"name": "Берсерк", "tag": "Защитник", "podacha": "Бросаешься в работу так, что забываешь о времени и усталости — объяснить потом, как это получилось, не можешь, просто получается. Другие ещё взвешивают риски, а ты уже внутри процесса.", "napravleniya": "спорт высоких достижений и экстремальные дисциплины, экстренная медицина и реанимация, антикризисное управление, боевые искусства, импровизационный театр и стендап, хирургия, спасательные и пожарные расчёты", "devoz": "Ярость, направленная в дело, превращается в способность не останавливаться.", "vizual": "резкий безостановочный жест, взгляд, не замечающий постороннего", "image": "cards/archetype/Берсерк.jpg"},
  {"name": "Бодхисаттва", "tag": "Проводник", "podacha": "Остаёшься рядом с чужой болью дольше, чем требуют приличия, и не торопишь выздоровление — у боли своё время. То, что ты несёшь, не объясняется словами: считывается по тому, как рядом с тобой стихает паника.", "napravleniya": "психотерапия и духовное сопровождение, хосписная и паллиативная помощь, монашеское и религиозное служение, работа с кризисными состояниями, преподавание философии и этики, супервизия помогающих специалистов, социальное служение", "devoz": "Помощь держится дольше, чем чужое терпение.", "vizual": "простое одеяние, ровный взгляд, направленный на собеседника", "image": "cards/archetype/Бодхисаттва.jpg"},
  {"name": "Лидер", "tag": "Защитник", "podacha": "Берёшь слово, когда группа ещё молчит от растерянности, и берёшь на себя последствия, если решение оказалось неверным. За тобой идут по одной причине: ты держишь направление, когда остальные его теряют.", "napravleniya": "управление командами и бизнесом, армия и силовые структуры, политика и государственное управление, предпринимательство, спортивное тренерство, экспедиционное руководство, антикризисный менеджмент", "devoz": "Ответственность занимает место раньше, чем должность.", "vizual": "прямая осанка, голос, который не повышают, чтобы услышали", "image": "cards/archetype/Лидер.jpg"},
  {"name": "Клоун", "tag": "Артист", "podacha": "Находишь смешное в самый неподходящий момент — и именно тогда оно нужнее всего. После тебя в комнате физически легче дышать, будто кто-то открыл окно.", "napravleniya": "стендап и разговорный юмор, цирковое искусство и клоунада, комедийная актёрская работа, ведение мероприятий, арт-терапия через игру, сценарии для развлекательного контента, работа с детскими коллективами", "devoz": "Смех расчищает место там, где тяжесть держала оборону.", "vizual": "яркая деталь в одежде, преувеличенный, но точный жест", "image": "cards/archetype/Клоун.jpg"},
  {"name": "Мать Земля", "tag": "Даритель", "podacha": "Замечаешь, кто не поел и не поспал, раньше, чем это скажут вслух, и тут же находишь, чем накормить или укрыть. Дом с тобой внутри становится местом, куда хочется вернуться, — стены здесь ни при чём, дело в том, кто ждёт.", "napravleniya": "семейная психология и консультирование, гостиничный и ресторанный бизнес, сельское хозяйство и фермерство, педагогика раннего возраста, патронаж и уход, кулинария как профессия заботы, экопоселения и общинные проекты", "devoz": "Забота заметна по тому, что накормлено, укрыто и услышано вовремя.", "vizual": "тёплые тона в одежде, руки, всегда чем-то заняты", "image": "cards/archetype/Мать_Земля.jpg"},
  {"name": "Фея-Крестная", "tag": "Даритель", "podacha": "Угадываешь желание раньше, чем человек успевает его сформулировать, и находишь способ исполнить именно то, о чём боялись просить. Обычная вещь в твоих руках оказывается ровно тем, чего не хватало — весь фокус в точности попадания.", "napravleniya": "ивент-индустрия и организация подарков-сюрпризов, персональный шопинг и стилистика, продюсирование креативных проектов, свадебная индустрия, брендинг подарочных продуктов, детские праздники, коучинг целеполагания", "devoz": "Дар угадывать желание стоит дороже, чем дар его исполнить.", "vizual": "неожиданная деталь-сюрприз в образе, лёгкий взмах руки перед вручением", "image": "cards/archetype/Фея-Крестная.jpg"},
  {"name": "Друг", "tag": "Даритель", "podacha": "Говоришь правду даже тогда, когда легче было бы промолчать, и не исчезаешь, когда обстоятельства перестают быть удобными. Такую дружбу найти непросто — а у тебя она есть.", "napravleniya": "командная работа и HR, наставничество и менторство, комьюнити-менеджмент и социальные проекты, спортивные команды, партнёрское предпринимательство, психологическое консультирование, журналистика и правозащита", "devoz": "Дружба заметна там, где обстоятельства перестали быть удобными.", "vizual": "рука протянута первой, без выжидания", "image": "cards/archetype/Друг.jpg"},
  {"name": "Гений", "tag": "Творец", "podacha": "Соединяешь две мысли, между которыми никто раньше не видел связи, — получившееся решение оказывается настолько простым, что странно, почему до него не додумались раньше. Черновик на салфетке у тебя иногда весит больше, чем чужая готовая презентация.", "napravleniya": "научные исследования и изобретательство, программирование и архитектура сложных систем, композиция и создание музыки, стратегический консалтинг, интеллектуальный спорт, инженерия и промышленный дизайн, теоретическая наука", "devoz": "Открытие — это связь, которую раньше никто не потрудился заметить.", "vizual": "рассеянный взгляд, направленный внутрь, резкая точность в момент найденного решения", "image": "cards/archetype/Гений.jpg"},
  {"name": "Бог", "tag": "Даритель", "podacha": "Даёшь из избытка — хватает даже тем, кто не просил. Там, где другие видят стену, ты уже видишь обход.", "napravleniya": "филантропия и крупная благотворительность, инвестирование и меценатство, продюсирование масштабных проектов, духовное наставничество, управление фондами и наследием, девелопмент инфраструктуры, спонсорство искусства и науки", "devoz": "Настоящее изобилие раздаёт себя, не считая.", "vizual": "широкий открытый жест дарения, взгляд поверх собственной выгоды", "image": "cards/archetype/Бог.jpg"},
  {"name": "Богиня", "tag": "Даритель", "podacha": "Держишь в одном взгляде нежность и власть, и ни одно не отменяет другое. Спор рядом с тобой быстро упирается в то, ради чего вообще начался, и как-то сам собой теряет смысл продолжаться.", "napravleniya": "психотерапия и работа с телесностью, сексологические и тантрические практики, искусство и скульптура, духовные и жреческие практики, руководство женскими сообществами, писательство и мифология, целительские практики", "devoz": "Мудрость не выбирает между силой и нежностью — держит оба.", "vizual": "тяжёлое украшение на открытой шее", "image": "cards/archetype/Богиня.jpg"},
  {"name": "Лекарь", "tag": "Проводник", "podacha": "Узнаёшь чужую боль по собственной похожей ране и не делаешь вид, что знаешь рецепт для всех. Рядом с тобой не стыдно всё ещё не оправляться до конца — ты тоже не изображаешь, что зажило.", "napravleniya": "медицина и клиническая практика, психотерапия и психиатрия, реабилитология, народная и альтернативная медицина, супервизия помогающих специалистов, работа с зависимостями, паллиативная помощь", "devoz": "Право лечить подтверждает собственная залеченная рана.", "vizual": "простая одежда, ладони, которые не спешат прикоснуться", "image": "cards/archetype/Лекарь.jpg"},
  {"name": "Герой", "tag": "Защитник", "podacha": "Делаешь шаг вперёд в тот момент, когда остальные ещё просчитывают риски, — ставишь на карту то, что действительно жалко терять. После тебя ситуация уже не может остаться прежней.", "napravleniya": "спасательные службы и МЧС, военная служба, экстренная медицина, предпринимательство на грани риска, адвокатура в резонансных делах, каскадёрская работа, журналистские расследования в опасных условиях", "devoz": "Смелость — это то, что поставлено на карту, не отсутствие страха.", "vizual": "шаг вперёд, когда остальные ещё стоят", "image": "cards/archetype/Герой.jpg"},
  {"name": "Верховный Жрец", "tag": "Проводник", "podacha": "Говоришь о сложном так, что оно вдруг становится простым, — слушающий на секунду перестаёт бояться. Между вопросом и ответом выдерживаешь паузу: место для чужого ответа, не занятое собой.", "napravleniya": "духовное наставничество, психотерапия и супервизия, преподавание и лекции, издательское дело и редактура смыслов, консалтинг по ценностям в бизнесе, медиация и посредничество, священнослужение", "devoz": "Мост держится, пока по нему кто-то идёт.", "vizual": "тёмная простая ткань без узора, руки спокойно сложены, взгляд на уровне собеседника, не выше", "image": "cards/archetype/Верховный_Жрец.jpg"},
  {"name": "Хозяйка", "tag": "Даритель", "podacha": "Ставишь чайник раньше, чем гость успевает сказать, что замёрз. Помнишь, кто с сахаром, кто без, — мелкая деталь, которую держишь в памяти, потому что так ты любишь.", "napravleniya": "гостиничный и ресторанный бизнес, ивент-менеджмент, дизайн интерьеров, кулинария и кондитерское дело, HR и забота о команде, семейная терапия, уход и патронаж", "devoz": "Дом держится не на стенах, а на том, кто помнит, кому налить чай.", "vizual": "фартук поверх домашней одежды, стол уже накрыт до того, как гости сели за него", "image": "cards/archetype/Хозяйка.jpg"},
  {"name": "Справедливый", "tag": "Защитник", "podacha": "Не отводишь взгляд, когда выгоднее промолчать, и называешь вещи так, как они есть, даже если это портит отношения с нужными людьми. Такая честность окупается там, где важнее быть тем, кому можно верить, чем понравиться.", "napravleniya": "юриспруденция и адвокатура, судебная система, журналистика-расследования, комплаенс и антикоррупционный контроль, правозащитная деятельность, медиация, аудит", "devoz": "Я на стороне правды, даже когда она неудобна.", "vizual": "прямая спина, минимум украшений, документы разложены по порядку на столе", "image": "cards/archetype/Справедливый.jpg"},
  {"name": "Король", "tag": "Защитник", "podacha": "Принимаешь решение и несёшь его последствия лично — не спрятаться за чужим мнением. Власть в твоих руках служит тем, кем ты руководишь: должность такого сама по себе не гарантирует.", "napravleniya": "топ-менеджмент, государственное управление, командные должности в армии и силовых структурах, спортивное капитанство и тренерство, семейный бизнес, кураторство крупных проектов, управление образованием", "devoz": "Власть, которая не служит другим, мне не нужна.", "vizual": "занимает место во главе стола без объявления об этом — просто садится, и разговор перестраивается вокруг него", "image": "cards/archetype/Король.jpg"},
  {"name": "Девушка", "tag": "Артист", "podacha": "Сразу замечаешь, что за окном пошёл снег, и бросаешь всё, чтобы посмотреть. Рядом с тобой люди вспоминают, что можно хотеть чего-то просто потому, что хочется.", "napravleniya": "анимация детских и семейных мероприятий, блогинг и лёгкий контент, творческие мастерские, модельный и модный бизнес, флористика, педагогика младших классов, event-индустрия", "devoz": "Я ещё не решила, кем стану, — и в этом моя свобода.", "vizual": "яркий цвет в одежде там, где остальные выбрали бы нейтральный, лёгкая походка вприпрыжку", "image": "cards/archetype/Девушка.jpg"},
  {"name": "Красавица", "tag": "Артист", "podacha": "Входишь в комнату — разговор на секунду становится мягче, без единого слова. Взгляд, каким ты смотришь на собеседника, сам по себе похож на комплимент.", "napravleniya": "модельный бизнес и подиум, визажное искусство и стилистика, актёрское мастерство, искусство и галерейное дело, дипломатия и представительские функции, luxury-индустрия, свадебная индустрия", "devoz": "Красота, за которой не видно человека, меня не интересует.", "vizual": "смотрит собеседнику в глаза дольше, чем принято, и не отводит взгляд первой", "image": "cards/archetype/Красавица.jpg"},
  {"name": "Возлюбленный", "tag": "Чувственный", "podacha": "Даже когда звонит телефон, ты остаёшься смотреть на собеседника. Рядом с тобой человек на время чувствует себя единственным в комнате, даже если комната полна.", "napravleniya": "психология отношений и парная терапия, режиссура свадебных и романтических событий, поэзия и написание песен, парфюмерное дело, event-фотография, консультирование по личным подаркам, шоколатье на заказ", "devoz": "Любить для меня — значит отпускать руку и оставаться рядом.", "vizual": "смотрит на собеседника, а не в телефон, даже когда телефон звонит", "image": "cards/archetype/Возлюбленный.jpg"},
  {"name": "Маг", "tag": "Проводник", "podacha": "Соединяешь то, что раньше никому не приходило в голову соединить, — и это вдруг начинает работать. Рискуешь раньше всех, потому что уже видишь, куда ведёт этот путь.", "napravleniya": "венчурное предпринимательство и стартапы, инновационный дизайн и R&D, режиссура и продюсирование, разработка IT-продуктов, стратегический бизнес-консалтинг, музыкальное продюсирование, архитектура", "devoz": "Новое начинается там, где я перестаю ждать разрешения.", "vizual": "на столе всегда что-то незаконченное и на вид гениальное, руки в постоянном движении", "image": "cards/archetype/Маг.jpg"},
  {"name": "Мужчина", "tag": "Чувственный", "podacha": "Берёшь на себя тяжёлую часть работы, не спрашивая, нужна ли помощь, — просто делаешь. Умеешь пошутить над собой раньше, чем это сделает кто-то другой.", "napravleniya": "строительство и инженерное дело, спорт — единоборства и командные виды, военное дело и охрана правопорядка, сельское хозяйство и фермерство, ремесленное производство, производственное предпринимательство, тренерская работа", "devoz": "Сила без направления — просто шум.", "vizual": "рукава закатаны ещё до того, как его попросили о помощи", "image": "cards/archetype/Мужчина.jpg"},
  {"name": "Вестник", "tag": "Артист", "podacha": "Передаёшь чужую идею так точно, будто это твоя собственная мысль, ничего не теряя по дороге. Узнаёшь новость раньше всех и не можешь не поделиться — знание, которое не пошло дальше, для тебя как письмо без адресата.", "napravleniya": "журналистика, PR и коммуникации, дипломатическая служба, переводческая деятельность, теле- и радиовещание, копирайтинг, преподавание и просвещение", "devoz": "Точность послания важнее моего авторства.", "vizual": "всегда на связи, телефон под рукой даже во время разговора с глазу на глаз", "image": "cards/archetype/Вестник.jpg"},
  {"name": "Мистик", "tag": "Проводник", "podacha": "Можешь час просидеть в тишине и не почувствовать, что время потрачено зря. Связь между вещами, которую остальные считают случайностью, для тебя обычное дело.", "napravleniya": "преподавание духовных и медитативных практик, трансперсональная психотерапия, теология и религиоведение, писательство и эссеистика, иконопись и сакральное искусство, музыкальная композиция, ретрит-фасилитация", "devoz": "Разделение — это то, что я перестал видеть первым.", "vizual": "долгая пауза перед ответом, взгляд слегка расфокусирован, будто смотрит сквозь", "image": "cards/archetype/Мистик.jpg"},
  {"name": "Нимфа", "tag": "Чувственный", "podacha": "Смеёшься всем телом, не заботясь, как это выглядит со стороны. О тех, кто рядом, заботишься так же естественно, как дышишь, — без надрыва, без чувства долга.", "napravleniya": "танец и хореография, телесные практики и соматика, актёрское мастерство, фитнес-индустрия, ландшафтный дизайн и работа с растениями, модельный бизнес, преподавание йоги", "devoz": "Живость не изображают — в ней просто остаются.", "vizual": "движется, даже стоя на месте: вес тела свободно перетекает с ноги на ногу", "image": "cards/archetype/Нимфа.jpg"},
  {"name": "Мудрый Мужчина", "tag": "Проводник", "podacha": "Выслушиваешь вопрос до конца, прежде чем произнести хоть слово в ответ. Совет у тебя звучит коротко — лишнее давно отброшено.", "napravleniya": "наставничество и менторство в бизнесе, супервизия в психотерапии, executive-консультирование руководителей, преподавание и научное руководство, юридическое консультирование, экспертиза в профессиональных сообществах, работа с топ-менеджерами", "devoz": "Мудрость — это то, что осталось после того, как я перестал спешить с ответом.", "vizual": "говорит медленнее, чем остальные в комнате, и все невольно тоже снижают темп", "image": "cards/archetype/Мудрый_Мужчина.jpg"},
  {"name": "Мудрая Женщина", "tag": "Проводник", "podacha": "Помнишь детали чужой жизни, которые сам человек уже забыл, и возвращаешь их в нужный момент. Сложное рядом с тобой становится проще — просто потому что наконец называется своим именем.", "napravleniya": "семейная и парная терапия, менторство для женщин в бизнесе, преподавание и передача опыта, консультирование по вопросам материнства и семьи, литература и мемуаристика, телесные и целительские практики, коучинг", "devoz": "Ответ уже есть у вас — я только помогаю его услышать.", "vizual": "руки без спешки, чашка чая рядом даже тогда, когда разговор о тяжёлом", "image": "cards/archetype/Мудрая_Женщина.jpg"},
  {"name": "Оптимист", "tag": "Творец", "podacha": "После провала у тебя один вопрос: что теперь с этим делать. Команда рядом снова начинает двигаться, даже не заметив, в какой момент это произошло, — просто потому что ты уже смотришь на шаг вперёд.", "napravleniya": "предпринимательство и антикризисный менеджмент, продажи, спортивное тренерство, обучение и публичные выступления, венчурные и стартап-проекты, кризисный PR, реабилитационная медицина", "devoz": "Поражение — это опыт, который ещё не нашёл своего применения.", "vizual": "поднимается первым после общей неудачи и уже прикидывает следующий шаг", "image": "cards/archetype/Оптимист.jpg"},
  {"name": "Паладин", "tag": "Защитник", "podacha": "Встаёшь на сторону того, кого обижают, ещё до того, как тебя попросили о помощи. Несправедливость — личное дело, промолчать не получается, даже когда это было бы гораздо удобнее.", "napravleniya": "юриспруденция и правозащита, силовые структуры и служба безопасности, спасательные и волонтёрские организации, комплаенс и корпоративная этика, наставничество для трудных подростков, журналистские расследования, военная служба, защита прав потребителей", "devoz": "Пока есть несправедливость, у меня есть дело.", "vizual": "тяжёлая ткань и прямой крой одежды, рука, которая инстинктивно оказывается между собеседником и опасностью", "image": "cards/archetype/Паладин.jpg"},
  {"name": "Первопроходец", "tag": "Творец", "podacha": "Не задерживаешься там, где уже понятно, что искать больше нечего. Чемодан у тебя почти всегда наполовину собран.", "napravleniya": "предпринимательство, продюсирование, разведка новых рынков, экспедиционные и исследовательские профессии, венчурные проекты, журналистика на передовой", "devoz": "Я не останавливаюсь — я ищу следующий горизонт.", "vizual": "дорожная кожа и лён, взгляд направлен вперёд и чуть выше собеседника", "image": "cards/archetype/Первопроходец.jpg"},
  {"name": "Защитник", "tag": "Защитник", "podacha": "Замечаешь, кто в комнате остался без защиты, и разворачиваешься в его сторону раньше, чем прозвучала просьба о помощи. Силу используешь, чтобы удержать, — тихо, без демонстрации того, кто здесь главный.", "napravleniya": "социальная работа и опека над детьми, кризисные центры помощи пострадавшим, охрана правопорядка и служба безопасности, педиатрия и детская медицина, ювенальная юстиция, зоозащита и приюты для животных, служба спасения, тренерская работа с детьми в спорте", "devoz": "Моя сила — это чужая возможность не бояться.", "vizual": "простая практичная одежда, корпус развёрнут туда, где кому-то нужна защита", "image": "cards/archetype/Защитник.jpg"},
  {"name": "Добытчик", "tag": "Даритель", "podacha": "Находишь нужное там, где другие разводят руками, — контакт, редкую возможность. Делишься добытым без опасения, что не хватит на себя: найти получится снова.", "napravleniya": "предпринимательство и снабжение, сельское хозяйство и фермерство, логистика и снабженческие цепочки, промысел и рыболовство, финансовое планирование семьи, благотворительные фонды, ресторанный бизнес и кейтеринг, оптовая торговля", "devoz": "Там, где есть нужда, я нахожу способ её закрыть.", "vizual": "полные сумки или багажник машины, взгляд, что сразу считывает, кому чего не хватает", "image": "cards/archetype/Добытчик.jpg"},
  {"name": "Вечный Мальчик", "tag": "Творец", "podacha": "Заходишь в комнату — и в ней становится легче дышать. Играешь с идеями, которые для других давно стали серьёзными и тяжёлыми, и этим оживляешь застоявшееся.", "napravleniya": "геймдизайн и разработка игр, событийный маркетинг и шоу-бизнес, стендап и импровизационный театр, детская анимация и мультипликация, тревел-блогинг, стартапы и венчурные эксперименты, цирковое искусство, диджеинг и музыкальные вечеринки", "devoz": "Я играю с тем, что другие боятся трогать.", "vizual": "яркая деталь в одежде не по случаю, смех на полтакта раньше, чем у остальных", "image": "cards/archetype/Вечный_Мальчик.jpg"},
  {"name": "Королева", "tag": "Артист", "podacha": "Держишь целое вниманием к каждой детали. Собираешь вокруг разных людей так, что никто не остаётся лишним — вот что такое власть.", "napravleniya": "ивент-менеджмент и организация мероприятий, HR и корпоративная культура, ресторанный и гостиничный бизнес, wedding-индустрия, управление семейным бизнесом, дипломатия и переговоры, кураторство выставок и культурных проектов, социальное предпринимательство", "devoz": "Всё держится, потому что я его держу.", "vizual": "стол накрыт с расчётом на лишнего гостя, осанка, которая не меняется, даже когда все спорят", "image": "cards/archetype/Королева.jpg"},
  {"name": "Санта Клаус", "tag": "Даритель", "podacha": "Замечаешь, чего человеку не хватает, раньше, чем тот успевает попросить. Повод для подарка находишь свой, без расписания праздника, — и неожиданность делает дар настоящим.", "napravleniya": "благотворительность и фандрайзинг, event и подарочная индустрия, наставничество молодых специалистов, спонсорство и меценатство, социальное предпринимательство, ритейл подарков и праздничная индустрия, краудфандинг-платформы, корпоративная благотворительность", "devoz": "Отдаю — и от этого мир становится просторнее.", "vizual": "карманы и сумки всегда с чем-то для кого-то, память на то, что человек обронил в разговоре месяц назад", "image": "cards/archetype/Санта_Клаус.jpg"},
  {"name": "Шаман", "tag": "Проводник", "podacha": "Идёшь в ту часть разговора, которую остальные обходят стороной. Работаешь с тем, что человек ещё не может произнести вслух, и возвращаешься с ответом — готовый диагноз выдать было бы проще, ты выбираешь дольше.", "napravleniya": "психотерапия и консультирование, интегративная медицина, хосписная и паллиативная помощь, антропология и этнография, документальная режиссура, экспедиционные и полевые исследования, капелланство и духовное сопровождение, нон-фикшн писательство о человеке", "devoz": "Знаю дорогу туда, куда другие боятся заглянуть.", "vizual": "долгая пауза перед ответом, будто говорящий сверяется с тем, чего не видно собеседнику", "image": "cards/archetype/Шаман.jpg"},
  {"name": "Звезда", "tag": "Артист", "podacha": "Выходишь на сцену — и зал перестаёт разговаривать. Показываешь, чего может достичь тот, кто выкладывается полностью, без запасного плана.", "napravleniya": "исполнительские искусства и театр, музыкальная индустрия, публичные выступления и спикерство, модельный бизнес, спортивные соревнования высокого уровня, блогинг и личный бренд, телевидение и медиа, конкурсы и премии", "devoz": "Свет — это то, что остаётся после полной отдачи.", "vizual": "выход без запасного плана, взгляд, что находит задний ряд зала, а не первый", "image": "cards/archetype/Звезда.jpg"},
  {"name": "Силач", "tag": "Защитник", "podacha": "Берёшь на себя вес, который другие боятся даже подойти поднять. Расходуешь силу так, чтобы кто-то рядом мог наконец перевести дыхание.", "napravleniya": "спорт высоких достижений и силовые виды спорта, спасательные службы, военная и физическая подготовка, физическая терапия и реабилитация, строительство и тяжёлая промышленность, персональный тренинг, охрана и телохранители, пожарная служба", "devoz": "Держу столько, сколько нужно, чтобы никто не упал.", "vizual": "руки, которые первыми тянутся подхватить тяжёлое или падающее, тело, привыкшее работать на пределе и не показывать этого", "image": "cards/archetype/Силач.jpg"},
  {"name": "Тантрика", "tag": "Чувственный", "podacha": "Замечаешь тело и его сигналы там, где другие проскакивают мимо, — в голосе, в перемене дыхания собеседника. Читаешь тело как язык, которому большинство разучилось доверять — рядом с тобой сложно соврать.", "napravleniya": "телесно-ориентированная терапия, преподавание танца и пластики, парфюмерия и индустрия ароматов, кулинария и гастрономия высокого уровня, дизайн интерьеров и текстиля, тантра-практики и сексология, актёрское мастерство, wellness и спа-индустрия", "devoz": "Внимание к телу — это тоже форма ума.", "vizual": "медленный жест там, где другие спешат, ткань и материалы выбираются на ощупь, а не по картинке", "image": "cards/archetype/Тантрика.jpg"},
  {"name": "Учитель", "tag": "Проводник", "podacha": "Задаёшь вопрос, после которого собеседник смотрит на свою же мысль иначе. Готовый вывод разбираешь на части и предлагаешь собрать заново.", "napravleniya": "педагогика и преподавание, наставничество в бизнесе, разработка образовательных программ, научно-исследовательская работа, тренерская деятельность в спорте, авторские курсы и лекции, редактура и консультирование текстов, воспитание и работа с детьми", "devoz": "Учу проверять, а не соглашаться.", "vizual": "блокнот с вопросами, а не с готовыми ответами, привычка договаривать мысль до конца, даже когда аудитория уже кивает", "image": "cards/archetype/Учитель.jpg"},
  {"name": "Воин", "tag": "Защитник", "podacha": "Дисциплина у тебя не показная — держится там, где другие давно бы всё бросили. Страх ещё не успевает договорить свою реплику до конца, а решение уже принято, и тело идёт вперёд быстрее сомнения.", "napravleniya": "военная служба, единоборства и профессиональный спорт, предпринимательство в кризисных нишах, антикризисное управление, судебная практика, пожарная и спасательная служба, тренерская работа в боевых искусствах, служба безопасности", "devoz": "Решение уже принято — дальше только действие.", "vizual": "собранная поза перед началом дела, ровное дыхание там, где у других сбивается", "image": "cards/archetype/Воин.jpg"},
  {"name": "Шут", "tag": "Артист", "podacha": "Произносишь вслух то, что все в комнате уже подумали, но промолчали. Шуткой снимаешь напряжение там, где прямое слово вызвало бы скандал — смелости в этом больше, чем видно со стороны.", "napravleniya": "стендап и сатирическая журналистика, копирайтинг и реклама, сценарное мастерство для комедий, фасилитация сложных переговоров, карикатура и иллюстрация, ведение мероприятий, политическая сатира, преподавание через игру", "devoz": "Правда смешнее, когда её боятся сказать прямо.", "vizual": "пауза перед репликой, за которую комната успевает напрячься, прежде чем рассмеяться", "image": "cards/archetype/Шут.jpg"},
  {"name": "Женщина", "tag": "Чувственный", "podacha": "Держишь нить отношений в семье или команде, когда все остальные заняты задачами. Замечаешь, что между людьми испортилось, раньше, чем это стало проблемой — работа невидимая и незаменимая.", "napravleniya": "психология отношений и семейная терапия, HR и корпоративная культура, кураторство сообществ, event-индустрия и гостеприимство, дизайн и декор, социальная работа, медиация конфликтов, клиентский сервис и забота о клиентах", "devoz": "Забочусь о связи, когда все остальные заняты результатом.", "vizual": "рука на плече в нужный момент разговора, память на детали чужой жизни, которые никто больше не заметил", "image": "cards/archetype/Женщина.jpg"}
];

var SHADOWS = [
  {"name": "Предатель", "tag": "Разрушение_границ", "teny_podacha": "Даёшь слово и держишь его, пока это ничего не стоит. Как только появляется более выгодный вариант, соглашение перестаёт быть обязательным, а объяснение находится уже после того, как решение принято за спиной у того, кто доверился.", "risk_zona": "там, где нарушение легко скрыть, а выгода ощутима сразу", "devoz": "Слово держит цену, пока не появится предложение получше.", "vizual": "рукопожатие с другой рукой за спиной", "image": "cards/shadow/Предатель.jpg"},
  {"name": "Гуляка", "tag": "Избегание", "teny_podacha": "Тревогу заглушаешь тем, что под рукой, — едой, бокалом. Неприятное чувство перебиваешь вместо того чтобы разобрать, и когда оно возвращается, добавляется стыд за способ, которым его глушишь.", "risk_zona": "там, где неприятное чувство поднимается быстрее, чем находится способ с ним остаться", "devoz": "Лучше заесть, чем узнать, откуда голод.", "vizual": "бокал, который наливают раньше, чем задают вопрос", "image": "cards/shadow/Гуляка.jpg"},
  {"name": "Черная Вдова", "tag": "Дефицит", "teny_podacha": "Близость держишь на расстоянии вытянутой руки: обрываешь отношения раньше, чем в них появится настоящая зависимость, или вовсе не подпускаешь. За этим стоит старое убеждение — близость заканчивается вредом, и причиняют его именно твои руки.", "risk_zona": "там, где отношения подходят к точке настоящей близости и взаимной зависимости", "devoz": "Лучше разрушить первой, чем ждать, когда разрушат.", "vizual": "чёрное платье и взгляд, который держит на расстоянии двух шагов", "image": "cards/shadow/Черная_Вдова.jpg"},
  {"name": "Босс", "tag": "Контроль", "teny_podacha": "Позицию сверху используешь, чтобы решать за других, ставя перед фактом вместо вопроса. Несогласие считывается как неподчинение — в ответ идёт давление должностью, возрастом, тоном.", "risk_zona": "там, где есть формальная власть и некому оспорить решение", "devoz": "Кто наверху, тот и прав — пока некому возразить.", "vizual": "указательный палец и дверь кабинета, закрытая изнутри", "image": "cards/shadow/Босс.jpg"},
  {"name": "Задира", "tag": "Контроль", "teny_podacha": "Давишь словом, тоном или просто присутствием на того, кто слабее, и считаешь это заслуженным — раз проиграл, значит, так и было нужно. За нападением стоит страх однажды оказаться среди тех, кого задевают первыми.", "risk_zona": "там, где рядом есть кто-то слабее и некому за него вступиться", "devoz": "Ударить первым — единственный способ не оказаться тем, кого бьют.", "vizual": "сжатый кулак и плечи, развёрнутые для удара раньше, чем он нужен", "image": "cards/shadow/Задира.jpg"},
  {"name": "Мошенник", "tag": "Разрушение_границ", "teny_podacha": "Желаемое получаешь обходным путём — недоговариваешь, подменяешь часть правды на целую. Расплата откладывается, пока получается не встречаться взглядом с тем, кого обманываешь.", "risk_zona": "там, где можно взять без честного обмена и это долго не всплывёт", "devoz": "Правда нужна только тому, кого поймали.", "vizual": "карты, которые тасуют под столом", "image": "cards/shadow/Мошенник.jpg"},
  {"name": "Конкурент", "tag": "Разрушение_границ", "teny_podacha": "Не можешь находиться рядом, не сравнивая себя с тем, кто рядом, — чужой успех считывается как собственное поражение. Победа нужна, чтобы не столкнуться с потерей связи, которая пугает больше проигрыша, — результат тут почти ни при чём.", "risk_zona": "там, где рядом оказывается тот, кто может быть лучше", "devoz": "Пока кто-то впереди, связь кажется недоступной.", "vizual": "взгляд, что меряет чужой рост вместо разговора", "image": "cards/shadow/Конкурент.jpg"},
  {"name": "Критик", "tag": "Разрушение_границ", "teny_podacha": "Первым делом находишь, что не так, — в чужой работе, во внешности. За оценкой стоит страх, что оценят в ответ, и нападение случается раньше, чем успевают напасть на тебя.", "risk_zona": "там, где есть что оценить прежде, чем оценят", "devoz": "Заметить чужой промах — способ забыть про собственный страх.", "vizual": "прищур, который ищет изъян раньше приветствия", "image": "cards/shadow/Критик.jpg"},
  {"name": "Заклинатель", "tag": "Контроль", "teny_podacha": "Мысль направляешь как оружие — желаешь плохого, удерживаешь в голове образ чужого поражения. От этой силы достаётся тебе раньше всех — через вину, которая потом не отпускает.", "risk_zona": "там, где обида не находит прямого выхода и превращается в тайное желание зла", "devoz": "Проклятие держит того, кто его произносит, крепче, чем того, кому оно послано.", "vizual": "губы, шепчущие имя в темноте", "image": "cards/shadow/Заклинатель.jpg"},
  {"name": "Темная Богиня", "tag": "Контроль", "teny_podacha": "Мир, по твоим ощущениям, вращается вокруг тебя. Там, где решение оборачивается не в твою пользу, в ход идёт давление вместо спора — молчание, резкость, демонстрация того, кто здесь главный.", "risk_zona": "там, где решение принимается коллективно и признание может достаться не ей первой", "devoz": "Или по-моему, или никак.", "vizual": "взгляд, что проверяет, а не слушает", "image": "cards/shadow/Темная_Богиня.jpg"},
  {"name": "Разрушитель", "tag": "Контроль", "teny_podacha": "Тебе мало победы — важно, чтобы от соперника ничего не осталось. Крушишь чужие планы и надежды без разбора, а после находишь среди разрушенного то, что было дорого лично тебе.", "risk_zona": "там, где чужой успех или мечта стоят на пути к собственной цели", "devoz": "Побеждает тот, после кого нечего восстанавливать — включая себя.", "vizual": "сапог, что не выбирает, по чему идти", "image": "cards/shadow/Разрушитель.jpg"},
  {"name": "Дьявол", "tag": "Разрушение_границ", "teny_podacha": "Восстаёшь против любой власти над собой — правила существуют, чтобы их нарушать, согласие звучит как поражение. Бунт не приносит свободы: за ним обычно следует новый виток наказания себя за него.", "risk_zona": "там, где кто-то требует подчинения без права на возражение", "devoz": "Свобода начинается там, где можно всё, включая наказание себя за это.", "vizual": "усмешка на лице того, кто переступает черту, заранее зная цену", "image": "cards/shadow/Дьявол.jpg"},
  {"name": "Пьяница", "tag": "Избегание", "teny_podacha": "Когда подступает то, с чем трудно встретиться трезво, тянешься к бутылке раньше, чем к разговору. Облегчение временное — боль возвращается, и к ней прибавляется стыд за способ, которым её снимали.", "risk_zona": "там, где боль подступает быстрее, чем находится другой способ её выдержать", "devoz": "Дно легче найти, чем причину, по которой к нему шли.", "vizual": "рука на бутылке раньше, чем на телефоне", "image": "cards/shadow/Пьяница.jpg"},
  {"name": "Неудачник", "tag": "Самонападение", "teny_podacha": "К провалу готовишься заранее — отказываешься от попытки или бросаешь её на середине, чтобы не узнавать, получилось бы. Каждая несостоявшаяся попытка лишь подтверждает то, что и так считалось известным заранее.", "risk_zona": "там, где нужно рискнуть и узнать результат, не зная его наперёд", "devoz": "Легче проиграть заранее, чем узнать цену настоящей попытки.", "vizual": "плечи, ссутуленные ещё до результата", "image": "cards/shadow/Неудачник.jpg"},
  {"name": "Толстяк", "tag": "Дефицит", "teny_podacha": "Ешь, когда физического голода нет вовсе, — чтобы заполнить то, чего не хватает: внимания, покоя. Даже в хорошей форме тело меряешь весом; что оно способно сделать, отходит на второй план.", "risk_zona": "там, где не хватает чего-то другого, а еда оказывается под рукой быстрее всего", "devoz": "Лишний вес — то, что осталось, когда не хватило всего остального.", "vizual": "тарелка, наполненная раньше, чем прошёл голод", "image": "cards/shadow/Толстяк.jpg"},
  {"name": "Драчун", "tag": "Контроль", "teny_podacha": "Несогласие встречаешь раньше, чем успеваешь услышать его смысл, — голос идёт вверх, тело подаётся вперёд. Когда вспышка проходит, объяснение уже готово: довели, не оставили выбора.", "risk_zona": "там, где решение принимают без него или ставят под сомнение его правоту при свидетелях", "devoz": "Если ты сдался — значит, я был прав.", "vizual": "сжатый кулак, который ещё не ударил", "image": "cards/shadow/Драчун.jpg"},
  {"name": "Дурак", "tag": "Избегание", "teny_podacha": "Ошибку объясняешь собой — обстоятельства тут почти ни при чём. Новую задачу встречаешь с готовым прогнозом провала и берёшься за неё вполсилы: так легче потом списать результат на заранее предсказанную неудачу.", "risk_zona": "там, где нужно попробовать что-то впервые при свидетелях, без права на черновик", "devoz": "Раз ошибся один раз — таким и останусь.", "vizual": "недописанный черновик, который так и не открыли снова", "image": "cards/shadow/Дурак.jpg"},
  {"name": "Прячущийся", "tag": "Избегание", "teny_podacha": "Обещание, данное себе, — начать, сказать вслух, — остаётся невысказанным дольше, чем хочется признать: вслух оно стало бы обязательным. Взамен выбираешь то, что ни к чему не обязывает — готовишься, ждёшь момента. Момент не наступает.", "risk_zona": "там, где нужно назвать вслух то, что до этого можно было держать только в намерении", "devoz": "Пока не сказано вслух — можно ещё передумать.", "vizual": "приоткрытая дверь, за которой никого не видно", "image": "cards/shadow/Прячущийся.jpg"},
  {"name": "Инвалид", "tag": "Избегание", "teny_podacha": "Недомогание приходит вовремя — перед разговором, который страшно вести, перед решением, которое страшно принять. Слабость даёт то, что трудно попросить прямо: внимание, отсрочку.", "risk_zona": "там, где нужно взять на себя действие, последствия которого лягут только на него", "devoz": "Раз я не могу — с меня и спроса нет.", "vizual": "рука, которая тянется за помощью раньше, чем за делом", "image": "cards/shadow/Инвалид.jpg"},
  {"name": "Судья", "tag": "Самонападение", "teny_podacha": "Для себя суд идёт по другим правилам. Один промах помнишь дольше, чем десять побед подряд — прокручиваешь снова, будто пересмотр дела что-то исправит задним числом. Разобраться не хочется. Хочется осудить, и быстро.", "risk_zona": "там, где результат оказался хуже ожидаемого и есть время остаться с этим наедине", "devoz": "За каждую ошибку положено наказание — иначе она не считается.", "vizual": "увеличительное стекло, наведённое на единственный промах", "image": "cards/shadow/Судья.jpg"},
  {"name": "Бездельник", "tag": "Избегание", "teny_podacha": "К делу подступаешь так, будто оно должно сразу получиться безупречно, и там, где безупречность не гарантирована, откладываешь начало на потом. Чем выше собственная планка, тем убедительнее повод не начинать вовсе.", "risk_zona": "там, где результат будет виден другим и сравнение неизбежно", "devoz": "Не начну — не будет доказательства, что не справился.", "vizual": "список дел, переписанный набело вместо того, чтобы вычеркнуть хоть один пункт", "image": "cards/shadow/Бездельник.jpg"},
  {"name": "Распутник", "tag": "Разрушение_границ", "teny_podacha": "Потребность во внимании, в утешении переводишь на один и тот же язык — язык сексуального интереса, даже там, где речь шла совсем о другом. Другой человек в этом переводе перестаёт быть отдельным — становится тем, через кого добираешь недостающее.", "risk_zona": "там, где рядом оказывается тот, кто не может или не хочет отказать сразу", "devoz": "Если меня хотят — значит, я существую.", "vizual": "взгляд, который раздевает раньше, чем прозвучало имя", "image": "cards/shadow/Распутник.jpg"},
  {"name": "Мученик", "tag": "Самонападение", "teny_podacha": "Берёшь на себя больше, чем просили, а потом припоминаешь это как доказательство своей ценности. Чужой успех встречаешь внутренним счётом, не радостью: отдаёшь больше — где награда?", "risk_zona": "там, где чужая лёгкая удача оказывается рядом с его долгим и незамеченным вкладом", "devoz": "Моя боль — единственное, что у меня точно есть.", "vizual": "тарелка, отодвинутая, чтобы досталось другим", "image": "cards/shadow/Мученик.jpg"},
  {"name": "Скряга", "tag": "Дефицит", "teny_podacha": "Делиться — деньгами, вниманием — откладываешь до момента, когда запаса станет достаточно; сама мера достаточности постоянно отодвигается. Удержанное не расходуется — служит лишь доказательством, что вообще есть чем распоряжаться.", "risk_zona": "там, где чужая просьба совпадает с моментом, когда он и сам не уверен, что ресурса хватит", "devoz": "Отдать — значит остаться ни с чем.", "vizual": "полка, на которой хранится больше, чем когда-либо будет использовано", "image": "cards/shadow/Скряга.jpg"},
  {"name": "Монстр", "tag": "Контроль", "teny_podacha": "Собственную злость, желание держишь под таким плотным запретом, что, вырываясь, они выходят несоразмерно поводу. После вспышки на время убираешь себя из отношений, будто исчезновение — единственный способ больше никого не задеть.", "risk_zona": "там, где долго сдерживаемое раздражение встречает повод, слишком мелкий, чтобы его оправдать", "devoz": "Если меня узнают настоящим — не выдержат.", "vizual": "дверь, закрытая изнутри после того, как всё уже сказано", "image": "cards/shadow/Монстр.jpg"},
  {"name": "Убийца", "tag": "Контроль", "teny_podacha": "Отдельное решение — жить не по родительскому сценарию, выбрать иначе — проживаешь как предательство, за которое придётся расплачиваться. Близость с теми, от кого в этом смысле держишься в стороне, объясняешь занятостью, характером — чем угодно, кроме вины, которая стоит за дистанцией.", "risk_zona": "там, где его собственный успех оказывается больше, чем было у тех, от кого он отделился", "devoz": "Моё право жить по-своему кому-то стоило места.", "vizual": "телефон, набранный до половины номера и положенный обратно", "image": "cards/shadow/Убийца.jpg"},
  {"name": "Придира", "tag": "Самонападение", "teny_podacha": "Мелкую ошибку другого не пропускаешь мимо — отмечаешь вслух, возвращаешься к ней снова, даже когда вопрос давно закрыт. За разбором чужого промаха стоит потребность доказать: здесь решаю я, без меня не обходится.", "risk_zona": "там, где его мнение не спросили, а решение всё равно приняли", "devoz": "Если я не укажу на ошибку — меня не заметят.", "vizual": "разбор чужой ошибки, растянутый дольше, чем сама ошибка", "image": "cards/shadow/Придира.jpg"},
  {"name": "Сирота", "tag": "Избегание", "teny_podacha": "Своё место в семье или компании уступаешь первым делом — решение, мнение. Со временем тебя спрашивают всё реже, и это принимается как подтверждение того, что спрашивать было и не за чем.", "risk_zona": "там, где нужно заявить собственный интерес в кругу, который привык обходиться без него", "devoz": "Меньше меня — меньше поводов для чужого беспокойства.", "vizual": "стул, придвинутый к столу, но так и не занятый", "image": "cards/shadow/Сирота.jpg"},
  {"name": "Аутсайдер", "tag": "Избегание", "teny_podacha": "Прежде чем тебя успеют не принять, выходишь из круга заранее — опаздываешь к разговору, держишь дистанцию, которую потом называешь чужим выбором. Строгость, с которой судишь себя за инаковость, приписываешь окружающим, хотя именно ты выносишь эту оценку раньше всех.", "risk_zona": "там, где группа формируется без явного приглашения и войти нужно самому", "devoz": "Уйти первым — надёжнее, чем узнать, что не позвали.", "vizual": "разговор в соседней комнате, который слушают через стену", "image": "cards/shadow/Аутсайдер.jpg"},
  {"name": "Свинья", "tag": "Разрушение_границ", "teny_podacha": "Пустоту, которую трудно назвать, заполняешь тем, что можно взять сразу, — едой, тратой. Облегчение держится ровно до момента, когда возвращается стыд, а стыд становится поводом повторить то же самое снова.", "risk_zona": "там, где рядом никого нет и не с кем сверить, где остановиться", "devoz": "Раз мера уже нарушена — дальше можно не считать.", "vizual": "упаковка, открытая заново, хотя предыдущая ещё не убрана", "image": "cards/shadow/Свинья.jpg"},
  {"name": "Хищник", "tag": "Дефицит", "teny_podacha": "Замечаешь чужую слабость раньше, чем боль, которую причиняешь, и пользуешься ею без раздумий — ради выгоды, ради превосходства. Давно перестаёшь чувствовать, что происходит с другим человеком от твоих действий: чужие слёзы читаются как информация, не сигнал остановиться.", "risk_zona": "там, где рядом оказывается кто-то слабее — уставший, зависимый, неспособный дать отпор", "devoz": "Пока я забираю, я не чувствую, что забрали у меня.", "vizual": "взгляд, который оценивает добычу, не человека", "image": "cards/shadow/Хищник.jpg"},
  {"name": "Проститутка", "tag": "Разрушение_границ", "teny_podacha": "Соглашаешься на близость ради того, что за ней стоит, — денег, статуса. Тело участвует, а внимание уходит в сторону: считает, взвешивает цену сделки, пока сама близость проходит мимо.", "risk_zona": "там, где отношения держатся на обмене — тело в обмен на безопасность, внимание в обмен на статус", "devoz": "Если я не чувствую эту близость, значит, ничего своего я и не отдаю.", "vizual": "тело здесь, а сама уже подсчитывает", "image": "cards/shadow/Проститутка.jpg"},
  {"name": "Ханжа", "tag": "Самонападение", "teny_podacha": "Осуждаешь чужую сексуальность вслух и жадно слушаешь подробности — чем откровеннее рассказ, тем внимательнее слушаешь, а после припечатываешь выводом о том, как правильно жить. Собственное тело и желание держишь под таким же надзором, каким меряешь чужое.", "risk_zona": "там, где кто-то рядом говорит о теле, желании или сексе прямо, без стыда", "devoz": "Осуждая тебя, я на минуту разрешаю себе то, что запрещаю.", "vizual": "поджатые губы и жадные глаза", "image": "cards/shadow/Ханжа.jpg"},
  {"name": "Бунтарь", "tag": "Разрушение_границ", "teny_podacha": "Говоришь «нет» раньше, чем дослушиваешь предложение, — на правило, на договорённость, на любое давление извне срабатывает сопротивление, даже если само требование разумно. По факту споришь не с конкретным человеком. Споришь с тем, что кто-то вообще имеет право решать за тебя.", "risk_zona": "там, где есть правило, договорённость или фигура, наделённая правом решать", "devoz": "Если я не подчинюсь, значит, я всё ещё свободен.", "vizual": "скрещённые руки раньше, чем прозвучали слова", "image": "cards/shadow/Бунтарь.jpg"},
  {"name": "Раб", "tag": "Избегание", "teny_podacha": "Соглашаешься на унизительные условия и объясняешь это обстоятельствами, хотя выбор был — просто не разрешаешь себе его увидеть. Свобода пугает больше, чем зависимость: там, где нужно решать в одиночку, быстро находится причина, почему сейчас не время.", "risk_zona": "там, где появляется реальная возможность выбрать иначе и никто больше не решает за него", "devoz": "Пока кто-то распоряжается мной, мне не нужно отвечать за свою жизнь.", "vizual": "опущенные плечи и готовность согласиться раньше, чем дослушал", "image": "cards/shadow/Раб.jpg"},
  {"name": "Шлюха", "tag": "Разрушение_границ", "teny_podacha": "Выставляешь сексуальность напоказ и получаешь от этого ощутимую отдачу — внимание, власть, подтверждение своей ценности. Близость случается быстро и часто, а задержаться в одних отношениях, дать узнать себя не через тело — получается редко.", "risk_zona": "там, где нужно остаться в близости дольше, чем длится первое влечение, и быть узнанной не через тело", "devoz": "Пока меня хотят, мне не нужно доказывать, что я чего-то стою иначе.", "vizual": "тело выставлено вперёд, взгляд — в поисках реакции", "image": "cards/shadow/Шлюха.jpg"},
  {"name": "Тупица", "tag": "Избегание", "teny_podacha": "На ошибку отвечаешь немедленным приговором себе, минуя разбор происходящего, — либо прячешь её, либо превращаешь в шутку раньше, чем это сделают другие. Часто выбираешь не пробовать вовсе: без попытки не будет и доказательства обратного.", "risk_zona": "там, где нужно попробовать новое при свидетелях и есть риск ошибиться на виду", "devoz": "Если я не попробую, никто не докажет, что я туп.", "vizual": "рука, зависшая над кнопкой, которую так и не нажали", "image": "cards/shadow/Тупица.jpg"},
  {"name": "Террорист", "tag": "Контроль", "teny_podacha": "Свою правоту ставишь выше чужого согласия и готовишь удар заранее — копишь обиду, доказательства чужой неправоты, чтобы в нужный момент предъявить всё разом. Разрушаешь по плану. Порыв тут ни при чём — называешь это восстановлением справедливости.", "risk_zona": "там, где долго терпел несогласие с собой и накопил достаточно, чтобы дать ответ разом", "devoz": "Раз я прав, разрушение — это просто восстановление порядка.", "vizual": "спокойное лицо и заранее собранное досье", "image": "cards/shadow/Террорист.jpg"},
  {"name": "Вор", "tag": "Разрушение_границ", "teny_podacha": "Берёшь больше, чем полагается по договорённости, — время, чужие идеи. После взятого пустота остаётся прежней: чем больше присваиваешь, тем меньше чувствуешь на это честное право.", "risk_zona": "там, где взять можно незаметно и никто сразу не спросит, откуда", "devoz": "Если возьму достаточно, пустота наконец закончится.", "vizual": "карман, набитый тем, что не согревает", "image": "cards/shadow/Вор.jpg"},
  {"name": "Мучитель", "tag": "Контроль", "teny_podacha": "Наказываешь не за конкретный проступок, а чтобы восстановить пошатнувшееся чувство власти. Находишь слабое место другого человека и бьёшь именно туда — точно, повторно, с ощущением, что имеешь на это право.", "risk_zona": "там, где почувствовал собственную беспомощность и рядом оказался кто-то, кому можно её передать", "devoz": "Если тебе больно, значит, это я здесь решаю.", "vizual": "спокойные руки, делающие расчётливо больно", "image": "cards/shadow/Мучитель.jpg"},
  {"name": "Вампир", "tag": "Дефицит", "teny_podacha": "Втягиваешь в разговор, в дело — и выходишь из контакта с полным баком, пока собеседник остаётся выжатым. Момент, когда чужое внимание или забота стали топливом вместо подарка, проходит незамеченным.", "risk_zona": "там, где рядом есть человек, готовый отдавать без счёта, и можно брать, не спрашивая, сколько осталось", "devoz": "Мне нужно немного твоей силы — я ведь тоже отдаю, просто не считаю сколько.", "vizual": "разговор, после которого один сияет, а другой бледнеет", "image": "cards/shadow/Вампир.jpg"},
  {"name": "Жертва", "tag": "Самонападение", "teny_podacha": "Рассказываешь о случившемся так, что вина всегда оказывается снаружи. Сочувствие принимаешь охотно, а предложение что-то изменить встречаешь сопротивлением — статус жертвы удобнее, чем действие.", "risk_zona": "там, где признание своей роли в случившемся означало бы взять на себя действие и ответственность", "devoz": "Пока со мной поступают несправедливо, с меня нечего спрашивать.", "vizual": "рассказ о беде, повторённый слово в слово в третий раз", "image": "cards/shadow/Жертва.jpg"},
  {"name": "Злодей", "tag": "Разрушение_границ", "teny_podacha": "Берёшь то, что хочешь, и не задерживаешься на вопросе, чем это обернётся для другого, — сердце в этот момент закрыто, будто чужая потребность существует в другой комнате. Выигрываешь так, что кто-то рядом обязательно проигрывает, и тебя это не останавливает.", "risk_zona": "там, где своя выгода и чужой интерес прямо сталкиваются и выбирать нужно быстро", "devoz": "Если я не возьму первым, возьмут у меня.", "vizual": "рука, уже потянувшаяся за своим, пока другой ещё договаривает", "image": "cards/shadow/Злодей.jpg"},
  {"name": "Ведьма", "tag": "Разрушение_границ", "teny_podacha": "Считываешь чужие слабые места быстрее, чем человек успевает их осознать, и используешь это знание, чтобы управлять, — подводишь к нужному решению, выстраиваешь зависимость. Близость с тобой быстро превращается в игру, правила которой знаешь только ты.", "risk_zona": "там, где есть кто-то, кто ищет ответов и готов довериться без проверки", "devoz": "Раз я вижу больше, значит, мне решать, что тебе с этим делать.", "vizual": "улыбка, которая знает заранее, чем закончится разговор", "image": "cards/shadow/Ведьма.jpg"},
  {"name": "Раненый Лекарь", "tag": "Самонападение", "teny_podacha": "Помогаешь другим раньше, чем закрываешь собственную рану, — чем щедрее отдаёшь внимание, силы, тем незаметнее для себя истощаешься. Своя боль становится пропуском в право помогать: чем больше пережито, тем легче слышать чужое.", "risk_zona": "там, где собственная усталость или боль остаются без внимания, потому что рядом кто-то, кому явно хуже", "devoz": "Пока я исцеляю тебя, мне не обязательно признавать, что я сам не исцелён.", "vizual": "перевязывает чужую рану, забыв про свою", "image": "cards/shadow/Раненый_Лекарь.jpg"}
];

var LINKS = [
  {"archetype_tag": "Проводник", "shadow_tag": "Самонападение", "konflikt": "Путь для других видишь раньше, чем они сами его нащупают, — а для себя эта ясность вдруг пропадает. Стоит не суметь помочь, и та же мудрость, которой освещаешь чужую дорогу, разворачивается против тебя с вопросом: почему не видишь раньше, почему не предупреждаешь вовремя.", "slepaya_zona": "Другим прощение даёшь легко. Себе — почти никогда: собственная вина держится дольше, чем чья-либо ещё.", "integraciya": "Взгляд, которым ты разбираешь чужой провал без суда, — редкий дар. Наведи его один раз на себя, и {shadow} перестаёт быть приговором, становится ещё одним путём, который {arche} в тебе, как всегда, умеет разглядеть.", "manera": "Ты говоришь неторопливо, оставляешь паузу, чтобы собеседник сам дошёл до ответа. Но стоит речи зайти о твоей собственной работе, тон меняется: перебиваешь себя раньше, чем это сделает кто-то другой, и правишь уже сказанное на ходу."},
  {"archetype_tag": "Проводник", "shadow_tag": "Дефицит", "konflikt": "Знанием делишься щедро — с кем угодно, в любое время. Самое ценное понимание придерживаешь про запас, будто, отдав его целиком, ничего не останется — особенно там, где дар не оценили так, как рассчитываешь.", "slepaya_zona": "Щедрость незаметно переходит в накопление. Подходящий случай, для которого бережёшь лучшее, почему-то не наступает.", "integraciya": "{shadow} копится там, где забываешь: мудрость не убывает от раздачи, только через неё и подтверждает себя. Отдай именно ту часть, что бережёшь больше всего, — и {arche} в тебе получает ещё один источник, из которого не жалко черпать.", "manera": "Объясняешь щедро — вопрос за вопросом, шаг за шагом. Самую сильную мысль придерживаешь напоследок, будто выложить её сразу означало бы остаться без козыря в разговоре."},
  {"archetype_tag": "Проводник", "shadow_tag": "Контроль", "konflikt": "Пока тебя слушают, ведёшь через понимание — терпеливо, шаг за шагом. Видение встречает сопротивление, и терпение кончается быстрее, чем хотелось бы: вместо диалога включается давление, хотя называется это всё ещё «я веду».", "slepaya_zona": "Где кончается «я вижу дальше» и начинается «я решаю за тебя» — вопрос, который не задаёшь себе вовремя.", "integraciya": "Верни терпению место там, где хочется продавить. {arche} умеет вести, не толкая, — и {shadow} перестаёт быть требованием подчиниться, становится способом показать дорогу и дать пройти её самостоятельно.", "manera": "Ведёшь разговор мягко, вопросами, а не готовыми выводами. Но стоит собеседнику пойти не в ту сторону, мягкость сменяется указанием: «нет, вот так»."},
  {"archetype_tag": "Проводник", "shadow_tag": "Избегание", "konflikt": "Для других всегда находится ясный путь вперёд. Для себя — только не сейчас: заявить о собственном прозрении вслух, взять за него ответственность на виду у всех — и выбираешь тень.", "slepaya_zona": "Прозрение, которым могла бы поделиться, прячешь под предлогом подходящего момента. Вслух оно так и не звучит.", "integraciya": "Путь становится настоящим только там, где по нему пройдёшь лично, на виду. {arche} это знает — сделай шаг туда, где обычно оставалась в тени, и {shadow} перестаёт быть укрытием, становится ещё одной дорогой, которую умеешь показывать другим.", "manera": "О чужом пути говоришь ясно и подробно. О собственном — расплывчато, обходишь конкретику ровно там, где нужно бы назвать дату, цифру, обязательство."},
  {"archetype_tag": "Проводник", "shadow_tag": "Разрушение_границ", "konflikt": "Роль проводника открывает доступ туда, куда обычно не пускают, — к чужой уязвимости. Обычно это доверие бережёшь. Момент, где его можно обратить в свою пользу, стирает границу между «веду» и «пользуюсь» быстрее, чем хочется признать.", "slepaya_zona": "Помощь и власть над чужой тайной — разница, которую легко потерять из виду. Знаешь больше — а уже используешь это знание как рычаг.", "integraciya": "Доверие, которое даёт роль проводника, верни туда, откуда оно взялось. {shadow} перестаёт быть властью над чужой тайной, становится ещё одним доказательством, что {arche} в тебе достоин доверия.", "manera": "Задаёшь вопрос — и по факту уже знаешь ответ, которого добиваешься. Разговор с тобой быстро превращается в мягкий допрос: вопросы звучат как вопросы, а работают как утверждения."},
  {"archetype_tag": "Защитник", "shadow_tag": "Самонападение", "konflikt": "Дерёшься за кого угодно — кроме себя. Там, где нужно встать за другого, реакция мгновенная, граница ясная. В момент, когда защитить не вышло, та же решимость разворачивается на сто восемьдесят градусов и бьёт по тебе.", "slepaya_zona": "Раненых защищают. Ты обычно на другой стороне этой фразы — щитом, не тем, кого прикрывают. Признать, что досталось тебе, значит на секунду выйти из привычной роли.", "integraciya": "{arche} не даёт бросить чужой бой на полпути — то же самое нужно и твоей защите себя. Разверни эту решимость один раз внутрь как охрану, не как трибунал, — и {shadow} наконец становится {arche}, только теперь на твоей стороне.", "manera": "Говоришь коротко, по делу, без обиняков — пока речь о чужом деле. О своей ошибке рассказываешь жёстче, чем требуется: тон судебного заседания, где судья и обвиняемый — один человек."},
  {"archetype_tag": "Защитник", "shadow_tag": "Дефицит", "konflikt": "На защиту других силы находится всегда — сколько ни попроси. Для себя эта щедрость почему-то не работает: ресурс уходит, а попросить о помощи в этот момент ощущается поражением — будто защитник не имеет права нуждаться в защите.", "slepaya_zona": "Это называешь бережливостью. На деле — отказ себе в том, что легко даёшь другим.", "integraciya": "{arche} умеет находить силу там, где её, казалось, не осталось, — просто обычно находка достаётся другим. Позволь себе на время оказаться под защитой, — и {shadow} перестаёт быть нехваткой, становится напоминанием, что забота положена и тебе.", "manera": "За другого вступаешься мгновенно и во весь голос. За себя говоришь тише — обходишься без части аргументов, будто отстаивать собственный интерес неприлично громко."},
  {"archetype_tag": "Защитник", "shadow_tag": "Контроль", "konflikt": "Защита у тебя настоящая — быстрая, надёжная. Там, где тот, кого защищаешь, хочет пойти собственным путём, забота незаметно превращается в требование: делай, как сказано, — я лучше знаю, чем это кончится.", "slepaya_zona": "Где заканчивается «оберегаю» и начинается «не отпускаю» — граница, которую легко потерять.", "integraciya": "Дай тому, кого оберегаешь, право на собственную ошибку. {arche} способен защищать, не забирая чужой выбор, — и {shadow} перестаёт быть клеткой, становится формой любви, которая умеет отпускать.", "manera": "Говоришь ясно, без экивоков. Несогласие встречаешь тоном, а не аргументом — он твердеет на полтона, и разговор превращается в объявление вместо обсуждения."},
  {"archetype_tag": "Защитник", "shadow_tag": "Избегание", "konflikt": "В чужой бой бросаешься не раздумывая — здесь всё понятно: кто прав, за кого встать. Конфликт касается лично тебя — и та же решимость куда-то девается. Проще снова найти чужую битву, чем разобраться со своей.", "slepaya_zona": "Служение другим и побег от себя — вещи, которые путаешь регулярно. Там безопаснее, чем в собственном конфликте, вот и весь секрет.", "integraciya": "{arche} не боится встать в бой — просто пока выбирает чужие. Разверни эту же смелость туда, где дело касается лично тебя, — {shadow} перестаёт быть укрытием, становится ещё одним полем, где умеешь побеждать.", "manera": "За чужие интересы говоришь без запинки. Когда конфликт касается тебя лично, находится причина сменить тему или отшутиться раньше, чем дойдёт до сути."},
  {"archetype_tag": "Защитник", "shadow_tag": "Разрушение_границ", "konflikt": "Сила у тебя настоящая, и обычно стоит на страже чужих границ. Там, где цель кажется достаточно важной — спасти, восстановить справедливость, — та же сила перешагивает через чужое «нет», с уверенностью, что цель оправдывает средства.", "slepaya_zona": "Момент, где начинаешь быть тем, от кого защищаешь, проходит незамеченным.", "integraciya": "{arche} знает цену чужой границе — потому и способен её защищать. Спроси разрешения там, где обычно действуешь ради благой цели, — {shadow} перестаёт быть силой, идущей напролом, становится доказательством, что твоя защита достойна доверия.", "manera": "Обычно говоришь по делу и уважаешь чужую границу в разговоре. Там, где цель ощущается достаточно важной, тон становится настойчивее, чем просили, — убеждаешь и после того, как прозвучало «нет»."},
  {"archetype_tag": "Даритель", "shadow_tag": "Самонападение", "konflikt": "Заботы хватает на всех вокруг — с запасом. Кто-то рядом остаётся недовольным, несмотря на всё уже отданное, и внутренний счёт открывается против тебя: значит, было недостаточно, значит, надо было больше.", "slepaya_zona": "Забота о себе держится за предательство заботы о других. Ресурс будто один на всех, а то, что достанется тебе, кто-то обязательно недополучит.", "integraciya": "{arche} умеет дать ровно то, что нужно, не считая. Позволь этой же щедрости однажды развернуться к себе, — {shadow} перестаёт быть виной за недостаточность, становится напоминанием: раздающему тоже причитается доля.", "manera": "Хвалишь щедро и быстро замечаешь чужую удачу вслух. О себе говоришь скупо — если и упомянешь свой вклад, тут же обесцениваешь его в ответ: «да ладно, ничего особенного»."},
  {"archetype_tag": "Даритель", "shadow_tag": "Дефицит", "konflikt": "Отдавать умеешь щедро — деньги, время, не считая. Взять обратно то же самое — гораздо сложнее, особенно там, где встаёт вопрос собственной цены: назначить её ощущается почти неприлично.", "slepaya_zona": "Бережливость к себе путаешь с жадностью. Взять для себя ощущается почти как отобрать у кого-то другого.", "integraciya": "{arche} точно знает, сколько кому нужно отдать. Примени этот же расчёт к себе — назови свою цену так же ясно, как называешь чужую нужду, — {shadow} перестаёт быть нехваткой, становится честным обменом, в котором ты наконец на обеих сторонах.", "manera": "Комплимент, поддержка, доброе слово — у тебя это льётся легко. Просьба о том же в свой адрес застревает в горле, звучит извиняющимся тоном, будто отнимает у кого-то время."},
  {"archetype_tag": "Даритель", "shadow_tag": "Контроль", "konflikt": "Даёшь искренне — обычно без всяких условий. Дар приняли не так, как ожидалось, — и включается невысказанное: раз отдано, значит, и решать, как этим распорядиться, положено тебе.", "slepaya_zona": "Скрытый счёт за щедрость не замечаешь вовсе. Заботишься, вроде бы, — а счёт всё равно выставлен, хоть никто не просил его открывать.", "integraciya": "{arche} умеет отдавать без всяких условий — в этом и есть сила дара. Отпусти то, что уже подарено, вместе с правом решать, как им распорядятся, — {shadow} перестаёт быть скрытым счётом, становится даром без мелкого шрифта.", "manera": "Разговор с тобой похож на подарок — тепло, внимание, забота без счёта. Но если дар приняли не так, как ждала, тон меняется на укоризненный, хоть слова остаются мягкими."},
  {"archetype_tag": "Даритель", "shadow_tag": "Избегание", "konflikt": "О других заботишься так, что видно издалека, — вовремя, по делу. О себе — почти не видно вовсе: нужна помощь, а вместо просьбы включается привычное «справлюсь без лишних слов».", "slepaya_zona": "Незаметность называешь скромностью. На деле это способ не просить о том, что нужно лично тебе.", "integraciya": "{arche} умеет заметить чужую нужду раньше, чем её назовут вслух. Позволь кому-то однажды заметить твою — попроси прямо, не жди, что угадают, — {shadow} перестаёт быть исчезновением, становится ещё одной формой заботы, теперь о себе.", "manera": "О чужих нуждах говоришь заботливо и вовремя. О своих — почти никогда: если спросят, как дела, ответ короткий, дежурный, закрывающий тему быстрее, чем она успела открыться."},
  {"archetype_tag": "Даритель", "shadow_tag": "Разрушение_границ", "konflikt": "Щедрость в тебе не знает границ, пока речь о том, что отдаёшь по своей воле. Помощь могли не просить вовсе, а щедрость всё равно решает, что она нужна, — и входит в чужую жизнь без спроса, с уверенностью, что делает добро.", "slepaya_zona": "Забота и навязывание — момент их путаницы проходит незамеченным. Помогаешь, вроде бы, — а на деле уже решаешь за другого, что ему нужно.", "integraciya": "{arche} способен дать именно то, что просили, — не больше и не меньше. Спроси прежде, чем отдавать, — {shadow} перестаёт быть вторжением, становится тем самым даром, которого действительно ждали.", "manera": "Заботу предлагаешь щедро, даже когда её не просили. Разговор незаметно превращается в советы, которые никто не заказывал, — из добрых намерений, но без спроса."},
  {"archetype_tag": "Творец", "shadow_tag": "Самонападение", "konflikt": "Создаёшь то, чего раньше не было, — в этом настоящая сила. Результат не дотягивает до первоначального замысла, и внутренний критик уничтожает созданное быстрее, чем оно доходит до мира.", "slepaya_zona": "Высокую планку путаешь с правом никогда не быть довольной собой. Требовательность будто делает работу лучше. На деле просто не даёт её закончить.", "integraciya": "{arche} умеет видеть, каким могло бы быть созданное в идеале, — в этом и источник замысла. Позволь готовому быть просто хорошим, — {shadow} перестаёт быть приговором результату, становится черновиком следующего шага.", "manera": "Идеи из тебя сыплются на ходу — перебиваешь себя на полуслове, договариваешь мысль скороговоркой. Стоит идее не сработать, и та же скорость обращается против тебя: разнос звучит быстрее и злее, чем сам план."},
  {"archetype_tag": "Творец", "shadow_tag": "Дефицит", "konflikt": "Идей всегда с избытком — приходят быстрее, чем успеваешь записать. Поделиться уже созданным — другое дело: там, где находку могут присвоить, щедрость сменяется закрытостью, будто отдать значит потерять право первенства.", "slepaya_zona": "Замысел держишь в себе дольше, чем нужно. Расчёта здесь ноль — только страх.", "integraciya": "{arche} создаёт достаточно, чтобы не бояться поделиться, — идеи не заканчиваются от того, что их показали. Отпусти найденное чуть раньше, чем комфортно, — {shadow} перестаёт быть страхом потери, становится доказательством, что источник не пересыхает.", "manera": "О новых замыслах говоришь взахлёб, заражаешь идеей с порога. О том, что уже создано и готово, — сдержаннее, будто показать готовое означает отдать что-то важное."},
  {"archetype_tag": "Творец", "shadow_tag": "Контроль", "konflikt": "Новое рождается легко — идеи, неожиданные связи. Чужая идея оказывается рядом с твоей, как конкурент, — и лёгкость исчезает: включается требование принять именно твою версию, без обсуждения.", "slepaya_zona": "Авторство путаешь с правом на последнее слово. Придумано тобой — и вроде бы решать тебе, хотя идея давно живёт своей жизнью.", "integraciya": "{arche} достаточно силён, чтобы выдержать чужую версию рядом со своей. Впусти обсуждение туда, где обычно настаиваешь, — {shadow} перестаёт быть борьбой за последнее слово, становится способом сделать идею лучше, чем она была одна.", "manera": "Идеи предлагаешь легко, одну за одной. Чужую версию слушаешь вполуха и почти сразу возвращаешься к своей: идея внутри уже готова, слушать дальше ощущается лишним."},
  {"archetype_tag": "Творец", "shadow_tag": "Избегание", "konflikt": "Идей всегда больше, чем можно унести, — в этом удовольствие и ловушка разом. Проект переходит от открытия к рутине, и новое манит сильнее, чем ответственность за начатое, — внимание уходит туда, где снова интересно.", "slepaya_zona": "Поиск нового и бегство от сделанного — вещи, которые смешиваешь легко. Увлекаешься другим, говоришь себе, — а по факту сбегаешь от того, что перестало быть лёгким.", "integraciya": "{arche} умеет начать то, чего раньше не было, — в этом и сила. Доведи хотя бы одно начатое до конца, прежде чем взяться за новое, — {shadow} перестаёт быть побегом, становится доказательством, что идеи умеют не только рождаться, но и жить.", "manera": "Про новую идею можешь говорить часами, глаза горят. Про старую, ещё не доведённую до конца, — переводишь тему, будто её и не было."},
  {"archetype_tag": "Творец", "shadow_tag": "Разрушение_границ", "konflikt": "Ради нового решения нарушаешь правила, которые для других — данность, не подлежащая обсуждению. Обычно в этом сила: увидеть, что закон можно переписать. Правило стоит на пути хорошей идеи — и перешагиваешь через него, не спрашивая, кого оно защищало.", "slepaya_zona": "Кого задевает разрушенный порядок — вопрос, который редко задаёшь себе.", "integraciya": "{arche} умеет менять систему, не разрушая тех, кто в ней живёт. Спроси, чему служило правило, прежде чем его нарушить, — {shadow} перестаёт быть сносом ради сноса, становится осознанным пересозданием.", "manera": "Ради хорошей идеи можешь спорить с кем угодно и о чём угодно. В пылу разговора легко перебиваешь и продавливаешь свою правоту, не заметив, что собеседник давно замолчал не потому, что согласен."},
  {"archetype_tag": "Артист", "shadow_tag": "Самонападение", "konflikt": "На сцене — в прямом или переносном смысле — сияешь без усилий, внимание держится само собой. Зал не отвечает тем восторгом, что ожидался, — и то же внимание разворачивается внутрь, придирчивым, безжалостным взглядом на себя.", "slepaya_zona": "Отсутствие аплодисментов читаешь как личный провал. Зал мог просто устать — эта мысль в голову почти не приходит.", "integraciya": "{arche} умеет светить, даже когда никто не смотрит, — свет не зависит от зрителя. Позволь себе сиять без подтверждения извне, — {shadow} перестаёт быть погашенным светом, становится паузой перед следующим выходом.", "manera": "На публике держишься уверенно, знаешь, где сделать паузу, чтобы услышали именно эту фразу. Наедине с собой та же требовательность к слову оборачивается разбором каждой сказанной фразы: не понравилось, сказано зря, дальше нужно иначе."},
  {"archetype_tag": "Артист", "shadow_tag": "Дефицит", "konflikt": "Вдохновение раздаёшь щедро — заражаешь энергией, зажигаешь комнату. Рядом появляется ещё один центр внимания — и щедрость сменяется ревностью: внимание, доставшееся кому-то другому, ощущается украденным у тебя.", "slepaya_zona": "От чужого взгляда зависишь сильнее, чем хочется признавать. На вид светишься независимо от чужого взгляда — хотя постоянно сверяешься, смотрят ли ещё.", "integraciya": "{arche} способен светить рядом с другим источником света, не тускнея от этого. Раздели сцену, не считая, кому досталось больше внимания, — {shadow} перестаёт быть ревностью, становится доказательством, что твоего света хватит даже там, где светят другие.", "manera": "Внимание удерживаешь легко — интонацией, паузой, точным словом. Если рядом появляется ещё один голос, который тоже слушают, твой тон становится острее, будто нужно перетянуть внимание обратно."},
  {"archetype_tag": "Артист", "shadow_tag": "Контроль", "konflikt": "Вести за собой через восхищение получается естественно — люди тянутся сами. Тебя вдруг не замечают в привычном центре — и лёгкое обаяние сменяется требовательностью: внимание уже не завоёвывают, ждут как должное.", "slepaya_zona": "Влияние и власть над залом — грань, которую стираешь незаметно для себя. Ведёшь за собой, вроде бы, — а требуешь, чтобы шли именно за тобой и никем другим.", "integraciya": "{arche} способен вести без принуждения — просто быть тем, за кем интересно идти. Отпусти требование внимания там, где раньше давила, — {shadow} перестаёт быть властью над залом, становится ещё одной причиной, по которой к тебе тянутся сами.", "manera": "Ведёшь разговор так, что за тобой хочется идти, — обаянием, а не напором. Если обаяние вдруг не срабатывает, включается требовательность: тон становится директивным, будто внимание должны, а не завоёвывают."},
  {"archetype_tag": "Артист", "shadow_tag": "Избегание", "konflikt": "На публике блистаешь без усилий — роль удаётся, зал реагирует. Нужно остаться собой без зрителей, один на один, без сцены и аплодисментов, — та же лёгкость пропадает, и ты незаметно исчезаешь из контакта.", "slepaya_zona": "Внимание публики путаешь с настоящей близостью. Знают тебя, вроде бы, — а знают только ту версию, что выходит на сцену.", "integraciya": "{arche} умеет быть собой на виду у всех — значит, способен быть собой и без свидетелей. Останься в комнате хотя бы на минуту дольше, когда зрителей нет, — {shadow} перестаёт быть исчезновением, становится ещё одним выходом, только для одного зрителя — себя.", "manera": "На сцене — в прямом или переносном смысле — говоришь ярко и уверенно. Один на один, без зрителей, голос становится тише и короче, будто без публики особо нечего сказать."},
  {"archetype_tag": "Артист", "shadow_tag": "Разрушение_границ", "konflikt": "Восхищение притягивается к тебе само — часть твоей природы. Чужое обожание можно использовать, открыть дверь, которая иначе осталась бы закрытой, — харизма незаметно превращается в инструмент, привычная черта стирается.", "slepaya_zona": "Харизма и манипуляция вниманием — граница тоньше, чем хотелось бы думать. Притягиваешь людей, вроде бы, — а уже используешь это притяжение как рычаг.", "integraciya": "{arche} притягивает внимание само по себе — ему не нужен рычаг. Оставь дверь закрытой там, где обожание могло бы её открыть, — {shadow} перестаёт быть инструментом, становится просто светом, который светит, ничего не требуя взамен.", "manera": "Умеешь расположить к себе одной фразой, одной интонацией. Там, где обожание можно использовать для своей цели, разговор незаметно превращается в инструмент — комплимент звучит как аванс, за который потом попросят."},
  {"archetype_tag": "Чувственный", "shadow_tag": "Самонападение", "konflikt": "Других ведёшь к близости легко — умеешь создать тепло, открыть пространство для доверия. Для себя иначе: позволяешь себе раскрыться по-настоящему, и следом приходит стыд за собственное желание, будто оно было ошибкой.", "slepaya_zona": "Открываешься сильно — и тут же слышишь внутри голос обвинения, хотя честность не преступление.", "integraciya": "{arche} умеет вести другого к теплу без стыда. Позволь себе тот же приём, что даёшь другим, — {shadow} перестаёт быть виной за желание, становится частью той самой близости, которую умеешь создавать.", "manera": "Говоришь так, что собеседник чувствует: его слышат телом, не только ушами — тон мягкий, темп подстроен под чужой. О собственном желании говоришь суше, короче, будто оправдываешься за то, что оно вообще есть."},
  {"archetype_tag": "Чувственный", "shadow_tag": "Дефицит", "konflikt": "Тепло и близость даришь легко — каждому, кто рядом, достаётся своя доля внимания. Настоящую глубину, ту, что стоит дороже всего, придерживаешь для себя, будто она закончится, если отдать её честно и до конца.", "slepaya_zona": "Осторожность путаешь с настоящей закрытостью. Не спешишь, говоришь себе, — а давно решаешь не показывать больше положенного.", "integraciya": "{arche} способен дарить тепло без счёта — значит, способен отдать и глубину, не боясь опустеть. Покажи чуть больше, чем комфортно, ровно один раз, — {shadow} перестаёт быть придержанной частью себя, становится доказательством, что тепла хватит даже на честность.", "manera": "Тепло в голосе у тебя настоящее, его хватает на любой разговор. Самую честную интонацию — ту, что выдаёт, что действительно важно, — придерживаешь, звучишь ровнее, чем чувствуешь."},
  {"archetype_tag": "Чувственный", "shadow_tag": "Контроль", "konflikt": "Близость, которую предлагаешь, настоящая — тёплая, без игры. Эта близость грозит закончиться не по твоему выбору — и желание, которое обычно объединяет, превращается в способ удержать: через ревность, через то, что не отпускает.", "slepaya_zona": "Желанность и власть над чужим желанием — вещи, которые путаешь легко. Хочешь остаться рядом, говоришь себе, — а уже не даёшь уйти.", "integraciya": "{arche} умеет притягивать, ничего не удерживая силой, — само тепло уже держит крепче любого контроля. Отпусти то, что хочет уйти, даже если больно, — {shadow} перестаёт быть удержанием, становится доказательством, что твоя близость не нуждается в клетке.", "manera": "Голосом умеешь притянуть без единого лишнего слова. Там, где притяжение грозит закончиться не по твоей воле, тон становится настойчивее — вопрос звучит как просьба остаться, а не как вопрос."},
  {"archetype_tag": "Чувственный", "shadow_tag": "Избегание", "konflikt": "Создать близость с кем угодно удаётся легко — притяжение, ощущение единственного человека в комнате. Связь перестаёт быть лёгкой игрой и начинает требовать обязательства — и ты исчезаешь раньше всех, будто настоящая близость уже не по твоей части.", "slepaya_zona": "Лёгкость в близости путаешь с неспособностью остаться. Такая натура, говоришь себе, — а именно там, где нужно задержаться, включается побег.", "integraciya": "{arche} умеет создать связь мгновенно — значит, способен удержать её дольше одного вечера. Останься на шаг дольше, чем обычно комфортно, — {shadow} перестаёт быть исчезновением, становится доказательством, что близость выдерживает не только лёгкость, но и время.", "manera": "С кем угодно умеешь заговорить так, что становится тепло и легко. Там, где разговор перестаёт быть лёгким и начинает требовать обязательства, интонация меняется раньше всего остального — короче, суше, отстранённее."},
  {"archetype_tag": "Чувственный", "shadow_tag": "Разрушение_границ", "konflikt": "Сила притяжения в тебе настоящая, без наигранности. Прямой путь к цели закрыт, обходной лежит через чьё-то желание, — та же сила незаметно превращается в инструмент: способ получить то, что просто так не дали бы.", "slepaya_zona": "Искренняя близость и разменная монета — где граница между ними, не всегда ясно. Нравишься человеку, думаешь, — а уже используешь это, чтобы получить своё.", "integraciya": "{arche} притягивает само по себе — ему не нужна цель, кроме самой близости. Оставь цель за порогом там, где обычно ведёшь к ней через чужое желание, — {shadow} перестаёт быть разменной монетой, становится тем, чем и было изначально, — настоящим притяжением, ничего не требующим взамен.", "manera": "Голос у тебя работает как приглашение — тёплый, притягивающий, без нажима. Там, где прямой путь закрыт, то же приглашение в голосе превращается в инструмент: интонация мягкая, а цель за ней — своя."}
];

